class NoAnsiFile(object):

    re_ansi = re.compile(r'\x1b[^m]*m')

    def __init__(self, fd):
        self.fd = fd

    def write(self, data):
        no_ansi_data = self.re_ansi.sub('', data)
        self.fd.write(no_ansi_data)

    def close(self):
        self.fd.close()

    def flush(self):
        self.fd.flush()


class IRStdFd(object):
    pass


class IRStdoutFd(IRStdFd):

    def __init__(self, print_stdout=True):
        self.print_stdout = print_stdout
        self.org_stdout = sys.stdout
        sys.stdout = self

    def write(self, data):
        if self.print_stdout:
            sys.__stdout__.write(data)
            sys.__stdout__.flush()
        for fd in IRSTDFDManager.fds:
            if not isinstance(fd, IRStdFd):
                fd.write(data)
                fd.flush()

    @staticmethod
    def flush():
        sys.__stdout__.flush()

    @staticmethod
    def close():
        sys.stdout = sys.__stdout__

    @staticmethod
    def fileno():
        return sys.__stdout__.fileno()


class IRStderrFd(IRStdFd):

    def __init__(self, print_stderr=True):
        self.print_stderr = print_stderr
        self.org_stderr = sys.stderr
        sys.stderr = self

    def write(self, data):
        if self.print_stderr:
            sys.__stderr__.write(data)
            sys.__stderr__.flush()
        for fd in IRSTDFDManager.fds:
            if not isinstance(fd, IRStdFd):
                fd.write(data)
                fd.flush()

    @staticmethod
    def flush():
        sys.__stderr__.flush()

    @staticmethod
    def close():
        sys.stderr = sys.__stderr__


class IRSTDFDManager(object):

    fds = set()

    def __init__(self, stdout=True, stderr=True, *fds):

        self.stdout = stdout
        self.stderr = stderr

        for fd in fds:
            self.add(fd)

        self.add(IRStdoutFd(print_stdout=self.stdout))
        self.add(IRStderrFd(print_stderr=self.stderr))

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def write(self, data):
        for fd in self.fds:
            fd.write(data)
            fd.flush()

    def flush(self):
        for fd in self.fds:
            fd.flush()

    def close(self):
        for fd in self.fds:
            fd.close()

    def add(self, fd):
        self.fds.add(fd)

