def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    m = re.match(r'^(v)(\d+)$', version)
    if not m:
        raise ObjectException("Version identifier '%s' does not match expected pattern" % version)
    prefix = m.group(1)
    num_str = m.group(2)
    num = int(num_str)
    next_num = num + 1
    # If zero-padded, maintain the same width
    if len(num_str) > 1 and num_str[0] == '0':
        return prefix + str(next_num).zfill(len(num_str))
    return prefix + str(next_num)

