def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if color:
        cmd_output_fn = cmd_output_p
    else:
        cmd_output_fn = cmd_output_b

    if not varargs:
        return cmd_output_fn(*cmd, **kwargs)

    partitions = partition(cmd, varargs, target_concurrency, _max_length)

    def run_cmd(partition_cmd: tuple[str, ...]) -> tuple[int, bytes]:
        return cmd_output_fn(*partition_cmd, **kwargs)

    with _thread_mapper(target_concurrency) as thread_map:
        results = list(thread_map(run_cmd, partitions))

    retcodes = [ret for ret, _ in results]
    stdouts = [out for _, out in results]

    return max(retcodes), b''.join(stdouts)

