def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    candidates = []
    for m in classes:
        for n in classes:
            if issubclass(n, m) and m is not n:
                break
        else:
            if m not in candidates:
                candidates.append(m)
    return candidates

