        required_when = option.get('required_when', None)
        if required_when is not None:
            # required_when is a condition like "other_arg == value"
            # or just "other_arg" meaning it's truthy
            condition_met = False
            if isinstance(required_when, str):
                # parse condition like "arg_name == value" or "arg_name"
                if '==' in required_when:
                    parts = [p.strip() for p in required_when.split('==')]
                    cond_arg_name = parts[0]
                    cond_value = parts[1]
                    cond_arg_value = args.get(cond_arg_name, None)
                    if cond_arg_value is not None and str(cond_arg_value) == cond_value:
                        condition_met = True
                else:
                    cond_arg_name = required_when.strip()
                    cond_arg_value = args.get(cond_arg_name, None)
                    if cond_arg_value:
                        condition_met = True
            elif isinstance(required_when, dict):
                for cond_arg_name, cond_value in required_when.items():
                    cond_arg_value = args.get(cond_arg_name, None)
                    if cond_arg_value is not None and str(cond_arg_value) == str(cond_value):
