def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = []

    for resource in app.spec.manifest:
        # Check if a custom observer schema has been specified for this resource
        try:
            get_kubernetes_resource_idx(app.spec.observer_schema, resource)
            # A custom observer schema exists for this resource, skip it
            continue
        except IndexError:
            # No custom observer schema exists, generate a default one
            pass

        # Generate a default observer schema with just the identifying fields
        schema = {
            "apiVersion": resource.get("apiVersion", ""),
            "kind": resource.get("kind", ""),
            "metadata": {
                "name": resource.get("metadata", {}).get("name", ""),
            },
        }

        # Include namespace if present
        if "namespace" in resource.get("metadata", {}):
            schema["metadata"]["namespace"] = resource["metadata"]["namespace"]

        default_observer_schema.append(schema)

    return default_observer_schema

