def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory
    # Check id
    if 'id' not in inventory:
        self.error('E036a')
    else:
        self.id = inventory['id']
        if not isinstance(self.id, str) or self.id == '':
            self.error('E036b', id=self.id)
    # Check type and spec version
    if 'type' not in inventory:
        self.error('E036c')
    else:
        inv_type = inventory['type']
        if extract_spec_version:
            # Try to extract spec version from type
            m = re.match(r'''https://ocfl.io/(\d+\.\d+)/spec/#inventory''', inv_type)
            if m:
                extracted = m.group(1)
                if extracted in self.spec_versions_supported:
                    self.spec_version = extracted
                else:
                    self.error('E038', type=inv_type)
            else:
                self.error('E038', type=inv_type)
        else:
            expected_type = 'https://ocfl.io/%s/spec/#inventory' % self.spec_version
            if inv_type != expected_type:
                self.error('E038', type=inv_type)
